import path from 'path';
import fs from 'fs';
import { generateIcons } from './icons.js';
import { log } from './logger.js';
export async function generateProject(config) {
    const projectDirectory = path.resolve(process.cwd(), 'webapkify');
    const packagePath = config.appId.replace(/\./g, '/');
    const mainDirectory = path.join(projectDirectory, 'app/src/main');
    const kotlinDirectory = path.join(mainDirectory, `kotlin/${packagePath}`);
    const resDirectory = path.join(mainDirectory, 'res');
    const assetsDirectory = path.join(mainDirectory, 'assets/www');
    log.step('Scaffolding Android project...');
    fs.mkdirSync(kotlinDirectory, { recursive: true });
    fs.mkdirSync(assetsDirectory, { recursive: true });
    fs.mkdirSync(resDirectory, { recursive: true });
    const webSource = path.resolve(process.cwd(), config.webDir ?? './dist');
    if (!fs.existsSync(webSource)) {
        log.error(`webDir not found: ${webSource}`);
        log.dim('Build your web app first (e.g. npm run build / vite build)');
        process.exit(1);
    }
    log.step('Copying web assets...');
    copyDirectorySync(webSource, assetsDirectory);
    log.success('Web assets copied');
    await generateIcons(config, resDirectory);
    writeStringsXml(config, path.join(resDirectory, 'values'));
    writeStylesXml(config, path.join(resDirectory, 'values'));
    writeColorsXml(config, path.join(resDirectory, 'values'));
    writeNetworkSecurityConfig(config, resDirectory);
    writeMainActivity(config, kotlinDirectory);
    writeAndroidManifest(config, mainDirectory);
    writeAppBuildGradle(config, projectDirectory);
    writeRootBuildGradle(config, projectDirectory);
    writeSettingsGradle(config, projectDirectory);
    writeGradleProperties(config, projectDirectory);
    writeLocalProperties(projectDirectory);
    writeGradleWrapperProps(projectDirectory);
    writeProguardRules(projectDirectory);
    log.success('Project scaffolding complete');
    return projectDirectory;
}
function writeMainActivity(config, kotlinDir) {
    const appId = config.appId;
    const webview = config.webview;
    const cacheModeMap = {
        DEFAULT: 'WebSettings.LOAD_DEFAULT',
        CACHE_ELSE_NETWORK: 'WebSettings.LOAD_CACHE_ELSE_NETWORK',
        NO_CACHE: 'WebSettings.LOAD_NO_CACHE',
        CACHE_ONLY: 'WebSettings.LOAD_CACHE_ONLY',
    };
    const statusBarCode = (() => {
        if (config.statusBar === 'transparent') {
            return `
        window.setFlags(
            android.view.WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,
            android.view.WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS
        )`;
        }
        if (config.statusBar === 'light') {
            return `
        @Suppress('DEPRECATION')
        window.decorView.systemUiVisibility = android.view.View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR`;
        }
        return '';
    })();
    const keepScreenOn = config.keepScreenOn ? `\n        window.addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)` : '';
    const geoClient = webview.geolocationEnabled ? `
        webView.webChromeClient = object : WebChromeClient() {
            override fun onGeolocationPermissionsShowPrompt(
                origin: String,
                callback: GeolocationPermissions.Callback,
            ) {
                callback.invoke(origin, true, false)
            }
        }`
        : '';
    const uaLine = webview.userAgentString ? `        settings.userAgentString = "${escapeKotlinString(webview.userAgentString)}"` : '        // userAgentString: using system default';
    const kotlin = `package ${appId}

import android.annotation.SuppressLint
import android.os.Bundle
import android.webkit.CookieManager
import android.webkit.GeolocationPermissions
import android.webkit.WebChromeClient
import android.webkit.WebSettings
import android.webkit.WebView
import android.webkit.WebViewClient
import androidx.appcompat.app.AppCompatActivity
import androidx.webkit.WebSettingsCompat
import androidx.webkit.WebViewFeature

/**
 * WebAPKify - generated MainActivity
 * Serves the bundled web app inside a hardware-accelerated, full-screen WebView.
 */
class MainActivity : AppCompatActivity() {
    private lateinit var webView: WebView

    @SuppressLint("SetJavaScriptEnabled")
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
${statusBarCode}${keepScreenOn}
        webView = WebView(this)
        setContentView(webView)

        val settings = webView.settings
        settings.javaScriptEnabled = ${bool(webview.javaScriptEnabled)}
        settings.javaScriptCanOpenWindowsAutomatically = ${bool(webview.javaScriptCanOpenWindowsAutomatically)}
        settings.domStorageEnabled = ${bool(webview.domStorageEnabled)}
        settings.databaseEnabled = ${bool(webview.databaseEnabled)}
        settings.loadsImagesAutomatically = ${bool(webview.loadsImagesAutomatically)}
        settings.blockNetworkImage = ${bool(webview.blockNetworkImage)}
        settings.blockNetworkLoads = ${bool(webview.blockNetworkLoads)}
        settings.mediaPlaybackRequiresUserGesture = ${bool(webview.mediaPlaybackRequiresUserGesture)}
        settings.useWideViewPort = ${bool(webview.useWideViewPort)}
        settings.loadWithOverviewMode = ${bool(webview.loadWithOverviewMode)}
        settings.builtInZoomControls = ${bool(webview.builtInZoomControls)}
        settings.displayZoomControls = ${bool(webview.displayZoomControls)}
        settings.textZoom = ${webview.textZoom ?? 100}
        settings.cacheMode = ${cacheModeMap[webview.cacheMode ?? 'DEFAULT']}
        settings.allowFileAccessFromFileURLs = ${bool(webview.allowFileAccessFromFileURLs)}
        @Suppress("DEPRECATION")
        settings.allowUniversalAccessFromFileURLs = ${bool(webview.allowUniversalAccessFromFileURLs)}
        settings.safeBrowsingEnabled = ${bool(webview.safeBrowsingEnabled)}
        settings.mixedContentMode = if (${bool(webview.allowMixedContent)}) {
            WebSettings.MIXED_CONTENT_ALWAYS_ALLOW
        } else {
            WebSettings.MIXED_CONTENT_NEVER_ALLOW
        }
        settings.setGeolocationEnabled(${bool(webview.geolocationEnabled)})
${geoClient}
${uaLine}

        if (WebViewFeature.isFeatureSupported(WebViewFeature.ALGORITHMIC_DARKENING)) {
            WebSettingsCompat.setAlgorithmicDarkeningAllowed(settings, ${bool(webview.algorithmicDarkeningAllowed)})
        }

        val cookieManager = CookieManager.getInstance()
        cookieManager.setAcceptCookie(${bool(webview.acceptCookies)})
        cookieManager.setAcceptThirdPartyCookies(webView, ${bool(webview.acceptThirdPartyCookies)})

        webView.webViewClient = WebViewClient()

        if (savedInstanceState != null) {
            webView.restoreState(savedInstanceState)
        } else {
            webView.loadUrl("file:///android_asset/www/index.html")
        }
    }

    override fun onSaveInstanceState(outState: Bundle) {
        super.onSaveInstanceState(outState)
        webView.saveState(outState)
    }

    @Deprecated("Deprecated in Java")
    override fun onBackPressed() {
        if (webView.canGoBack()) webView.goBack()
        else {
            @Suppress("DEPRECATION")
            super.onBackPressed()
        }
    }
}`;
    fs.writeFileSync(path.join(kotlinDir, 'MainActivity.kt'), kotlin);
    log.dim('  MainActivity.kt');
}
function bool(value) {
    return value === true ? 'true' : 'false';
}
function writeAndroidManifest(config, mainDirectory) {
    const permissions = config.permissions;
    const permMap = [
        [permissions.internet, 'android.permission.INTERNET'],
        [permissions.networkState, 'android.permission.ACCESS_NETWORK_STATE'],
        [permissions.wifiState, 'android.permission.ACCESS_WIFI_STATE'],
        [permissions.coarseLocation, 'android.permission.ACCESS_COARSE_LOCATION'],
        [permissions.fineLocation, 'android.permission.ACCESS_FINE_LOCATION'],
        [permissions.camera, 'android.permission.CAMERA'],
        [permissions.recordAudio, 'android.permission.RECORD_AUDIO'],
        [permissions.readExternalStorage, 'android.permission.READ_EXTERNAL_STORAGE'],
        [permissions.writeExternalStorage, 'android.permission.WRITE_EXTERNAL_STORAGE'],
        [permissions.readMediaImages, 'android.permission.READ_MEDIA_IMAGES'],
        [permissions.readMediaVideo, 'android.permission.READ_MEDIA_VIDEO'],
        [permissions.readMediaAudio, 'android.permission.READ_MEDIA_AUDIO'],
        [permissions.vibrate, 'android.permission.VIBRATE'],
        [permissions.receiveBootCompleted, 'android.permission.RECEIVE_BOOT_COMPLETED'],
        [permissions.postNotifications, 'android.permission.POST_NOTIFICATIONS'],
        [permissions.bluetooth, 'android.permission.BLUETOOTH'],
        [permissions.bluetooth, 'android.permission.BLUETOOTH_CONNECT'],
        [permissions.bluetooth, 'android.permission.BLUETOOTH_SCAN'],
        [permissions.nfc, 'android.permission.NFC'],
        [permissions.biometric, 'android.permission.USE_BIOMETRIC'],
        [permissions.fingerprint, 'android.permission.USE_FINGERPRINT'],
        [permissions.flashlight, 'android.permission.FLASHLIGHT'],
        [permissions.wakeLock, 'android.permission.WAKE_LOCK'],
        [permissions.foregroundService, 'android.permission.FOREGROUND_SERVICE'],
        [permissions.scheduleExactAlarm, 'android.permission.SCHEDULE_EXACT_ALARM'],
    ];
    const permLines = permMap.filter(([flag]) => flag).map(([, name]) => `    <uses-permission android:name="${name}" />`).join('\n');
    const netSecAttr = (config.clearTextDomains?.length || config.allowAllClearText) ? `\n        android:networkSecurityConfig="@xml/network_security_config"` : '';
    const xml = `<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android">

${permLines}

    <application
        android:allowBackup="${config.allowBackup}"
        android:hardwareAccelerated="${config.hardwareAccelerated}"
        android:icon="@mipmap/ic_launcher"
        android:roundIcon="@mipmap/ic_launcher"
        android:label="@string/app_name"
        android:supportsRtl="${config.supportsRtl}"
        android:theme="@style/AppTheme"${netSecAttr}>
        <activity
            android:name=".MainActivity"
            android:configChanges="orientation|screenSize|keyboardHidden"
            android:exported="true"
            android:screenOrientation="${config.orientation ?? 'unspecified'}"
            android:windowSoftInputMode="adjustResize">
            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
        </activity>
    </application>
</manifest>`;
    fs.writeFileSync(path.join(mainDirectory, 'AndroidManifest.xml'), xml);
    log.dim('  AndroidManifest.xml');
}
function writeStringsXml(config, directory) {
    fs.mkdirSync(directory, { recursive: true });
    fs.writeFileSync(path.join(directory, 'strings.xml'), `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <string name="app_name">${escapeXml(config.appName)}</string>
</resources>`);
    log.dim('  strings.xml');
}
function writeStylesXml(config, directory) {
    fs.mkdirSync(directory, { recursive: true });
    const parent = config.statusBar === 'dark' ? 'Theme.AppCompat.NoActionBar' : 'Theme.AppCompat.Light.NoActionBar';
    fs.writeFileSync(path.join(directory, 'styles.xml'), `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <style name="AppTheme" parent="${parent}">
        <item name="colorPrimary">@color/colorPrimary</item>
        <item name="colorPrimaryDark">@color/colorPrimaryDark</item>
        <item name="colorAccent">@color/colorAccent</item>
        <item name="android:windowBackground">@color/windowBackground</item>
        <item name="android:statusBarColor">@color/colorPrimaryDark</item>
    </style>
</resources>`);
    log.dim('  styles.xml');
}
function writeColorsXml(config, directory) {
    fs.mkdirSync(directory, { recursive: true });
    fs.writeFileSync(path.join(directory, 'colors.xml'), `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="colorPrimary">${config.themeColor ?? '#FFFFFF'}</color>
    <color name="colorPrimaryDark">${config.themeColor ?? '#FFFFFF'}</color>
    <color name="colorAccent">${config.themeColor ?? '#2196F3'}</color>
    <color name="windowBackground">${config.backgroundColor ?? '#FFFFFF'}</color>
</resources>`);
    log.dim('  colors.xml');
}
function writeNetworkSecurityConfig(config, resDirectory) {
    if (!config.clearTextDomains?.length && !config.allowAllClearText)
        return;
    const xmlDirectory = path.join(resDirectory, 'xml');
    fs.mkdirSync(xmlDirectory, { recursive: true });
    const body = config.allowAllClearText ? `    <base-config cleartextTrafficPermitted="true" />` : config.clearTextDomains.map(domain => `    <domain-config cleartextTrafficPermitted="true">
        <domain includeSubdomains="true">${domain}</domain>
    </domain-config>`).join('\n');
    fs.writeFileSync(path.join(xmlDirectory, 'network_security_config.xml'), `<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
${body}
</network-security-config>
`);
    log.dim('  network_security_config.xml');
}
function normalizeJvmTarget(raw) {
    const fallback = '21';
    if (!raw)
        return fallback;
    const cleaned = String(raw).trim();
    const parsedNumber = Number(cleaned);
    if (!Number.isFinite(parsedNumber))
        return fallback;
    if (parsedNumber >= 24)
        return '21';
    if (parsedNumber >= 21)
        return '21';
    if (parsedNumber >= 17)
        return '17';
    if (parsedNumber >= 11)
        return '11';
    return '1.8';
}
function writeAppBuildGradle(config, projectDir) {
    const build = config.build;
    const signing = config.signing;
    const normalizedJvmTarget = normalizeJvmTarget(build.jvmTarget);
    const storeFilePath = signing?.storeFile.replace(/\\/g, '/');
    const signingBlock = signing ? `
    signingConfigs {
        create("release") {
            storeFile       = file("${storeFilePath}")
            storePassword   = "${signing.storePassword}"
            keyAlias        = "${signing.keyAlias}"
            keyPassword     = "${signing.keyPassword}"
            enableV1Signing = ${signing.v1SigningEnabled ?? true}
            enableV2Signing = ${signing.v2SigningEnabled ?? true}
            enableV3Signing = ${signing.v3SigningEnabled ?? true}
            enableV4Signing = ${signing.v4SigningEnabled ?? false}
        }
    }` : '';
    const releaseSigningRef = signing ? `            signingConfig = signingConfigs.getByName("release")` : `            // No signing config provided - produces unsigned release APK`;
    const extraBuildConfig = Object.entries(build.extraProperties ?? {}).map(([key, value]) => `        buildConfigField("String", "${key}", "\\"${value}\\"")`).join('\n');
    const gradle = `plugins {
    id("com.android.application")
    id("org.jetbrains.kotlin.android")
}

android {
    namespace         = "${config.appId}"
    compileSdk        = ${config.compileSdk}
    buildToolsVersion = "${config.buildToolsVersion}"
${signingBlock}

    defaultConfig {
        applicationId = "${config.appId}"
        minSdk        = ${config.minSdk}
        targetSdk     = ${config.targetSdk}
        versionCode   = ${config.versionCode}
        versionName   = "${config.versionName}"
${extraBuildConfig}
    }

    buildTypes {
        debug {
            applicationIdSuffix = ".debug"
            isDebuggable        = true
        }

        release {
            isMinifyEnabled   = ${build.minifyEnabled}
            isShrinkResources = ${build.shrinkResources}
            proguardFiles(
                getDefaultProguardFile("proguard-android-optimize.txt"),
                "proguard-rules.pro"
            )
${releaseSigningRef}
        }
    }

    buildFeatures {
        buildConfig = true
    }

    compileOptions {
        sourceCompatibility = JavaVersion.toVersion("${normalizedJvmTarget}")
        targetCompatibility = JavaVersion.toVersion("${normalizedJvmTarget}")
    }

    kotlinOptions {
        jvmTarget = "${normalizedJvmTarget}"
    }

    applicationVariants.all {
        val variant = this
        variant.outputs.all {
            val output = this as com.android.build.gradle.internal.api.BaseVariantOutputImpl
            output.outputFileName = "${config.artifact}-\${variant.buildType.name}.apk"
        }
    }
}

dependencies {
    implementation("androidx.appcompat:appcompat:1.7.0")
    implementation("androidx.core:core-ktx:1.15.0")
    implementation("androidx.webkit:webkit:1.13.0")
}`;
    fs.mkdirSync(path.join(projectDir, 'app'), { recursive: true });
    fs.writeFileSync(path.join(projectDir, 'app/build.gradle.kts'), gradle);
    log.dim('  app/build.gradle.kts');
}
function writeRootBuildGradle(config, projectDirectory) {
    const build = config.build;
    fs.writeFileSync(path.join(projectDirectory, 'build.gradle.kts'), `plugins {
    id("com.android.application") version "${build.agpVersion}" apply false
    id("org.jetbrains.kotlin.android") version "${build.kotlinVersion}" apply false
}`);
    log.dim('  build.gradle.kts (root)');
}
function writeSettingsGradle(config, projectDirectory) {
    fs.writeFileSync(path.join(projectDirectory, 'settings.gradle.kts'), `pluginManagement {
    repositories {
        google {
            content {
                includeGroupByRegex("com\\\\.android.*")
                includeGroupByRegex("com\\\\.google.*")
                includeGroupByRegex("androidx.*")
            }
        }
        mavenCentral()
        gradlePluginPortal()
    }
}

dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "${config.appName}"
include(":app")`);
    log.dim('  settings.gradle.kts');
}
function writeGradleProperties(config, projectDirectory) {
    const extra = Object.entries(config.build?.extraProperties ?? {}).map(([key, value]) => `${key}=${value}`).join('\n');
    fs.writeFileSync(path.join(projectDirectory, 'gradle.properties'), `org.gradle.jvmargs=-Xmx4096m -Dfile.encoding=UTF-8
org.gradle.parallel=true
org.gradle.caching=true
org.gradle.configureondemand=true
android.useAndroidX=true
android.enableJetifier=true
kotlin.code.style=official
${extra}`);
    log.dim('  gradle.properties');
}
function writeLocalProperties(projectDirectory) {
    const candidates = [process.env.ANDROID_HOME, process.env.ANDROID_SDK_ROOT, process.env.LOCALAPPDATA ? path.join(process.env.LOCALAPPDATA, 'Android', 'Sdk') : undefined, process.env.USERPROFILE ? path.join(process.env.USERPROFILE, 'AppData', 'Local', 'Android', 'Sdk') : undefined,].filter((value) => Boolean(value && value.trim()));
    const sdkPath = candidates.find(candidate => fs.existsSync(candidate));
    if (!sdkPath) {
        log.error('Android SDK not found.');
        log.dim('Set ANDROID_HOME or ANDROID_SDK_ROOT to a valid Android SDK path.');
        log.dim('Example: C:/Users/<you>/AppData/Local/Android/Sdk');
        process.exit(1);
    }
    const normalizedSdkPath = sdkPath.replace(/\\/g, '/');
    const content = `## Generated by WebAPKify - do not commit
sdk.dir=${normalizedSdkPath}`;
    fs.writeFileSync(path.join(projectDirectory, 'local.properties'), content);
    log.dim(`  local.properties (${normalizedSdkPath})`);
}
function writeGradleWrapperProps(projectDirectory) {
    const directory = path.join(projectDirectory, 'gradle/wrapper');
    fs.mkdirSync(directory, { recursive: true });
    fs.writeFileSync(path.join(directory, 'gradle-wrapper.properties'), `distributionBase=GRADLE_USER_HOME
distributionPath=wrapper/dists
distributionUrl=https\\://services.gradle.org/distributions/gradle-8.10.2-bin.zip
networkTimeout=10000
validateDistributionUrl=true
zipStoreBase=GRADLE_USER_HOME
zipStorePath=wrapper/dists`);
    log.dim('  gradle-wrapper.properties');
}
function writeProguardRules(projectDirectory) {
    fs.mkdirSync(path.join(projectDirectory, 'app'), { recursive: true });
    fs.writeFileSync(path.join(projectDirectory, 'app/proguard-rules.pro'), `# WebAPKify ProGuard / R8 rules
-keepclassmembers class * {
    @android.webkit.JavascriptInterface <methods>;
}
-keep public class * extends android.app.Activity
-keep public class * extends android.webkit.WebViewClient
-keep public class * extends android.webkit.WebChromeClient`);
    log.dim('  proguard-rules.pro');
}
function copyDirectorySync(source, destination) {
    fs.mkdirSync(destination, { recursive: true });
    for (const entry of fs.readdirSync(source, { withFileTypes: true })) {
        const sourcePath = path.join(source, entry.name);
        const destinationPath = path.join(destination, entry.name);
        entry.isDirectory() ? copyDirectorySync(sourcePath, destinationPath) : fs.copyFileSync(sourcePath, destinationPath);
    }
}
function escapeXml(input) {
    return input.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}
function escapeKotlinString(input) {
    return input.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
}
